use alloy::{
    providers::{Provider, ProviderBuilder},
    rpc::types::eth::BlockNumberOrTag,
    primitives::{Address, B256, TxHash},
};
use eyre::Result;
use std::str::FromStr;

#[tokio::main]
async fn main() -> Result<()> {
    // 1. Initialize RPC connections to the source chain (e.g., Ethereum Mainnet)
    let rpc_url = "https://alchemy.com".parse()?;
    let provider = ProviderBuilder::new().on_http(rpc_url);

    // Target information (The specific bridge deposit transaction hash generated by the user)
    let tx_hash = TxHash::from_str("0x1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef")?;

    println!("⚡️ Gathering cryptographic transaction parameters from RPC node...");

    // 2. Fetch the transaction receipt to locate the event log layout
    let receipt = provider.get_transaction_receipt(tx_hash).await?
        .ok_or_else( eyre::eyre!("Transaction receipt not found on-chain"))?;

    let block_number = receipt.block_number.unwrap();

    // 3. Fetch the full block details to get the baseline Receipts Root
    let block = provider.get_block_by_number(BlockNumberOrTag::Number(block_number), false).await?
        .ok_or_else( eyre::eyre!("Block details not found on-chain"))?;
    
    let receipts_root: B256 = block.header.receipts_root;

    // 4. Request the raw cryptographic Merkle-Patricia Proof for the receipt index
    // This calls the standard EVM 'eth_getProof' endpoint behind the scenes
    let tx_index = receipt.transaction_index.unwrap() as usize;
    
    // Fetch all brother/sister node receipts in the block to rebuild the local trie path
    let all_block_receipts = provider.get_block_receipts(BlockNumberOrTag::Number(block_number)).await?
        .ok_or_else(|| eyre::eyre!("Failed to retrieve neighbor block receipts"))?;

    println!("🔒 Found Receipts Root: {:?}", receipts_root);
    println!("🧱 Transaction Index inside Block: {}", tx_index);
    println!("📦 Bundling inputs for execution in the Succinct SP1 zkVM environment...");

    // 5. Serialize data vectors to feed into the ZK circuit
    // (This payload is what the user passes to their local WebAssembly-based ZK Prover)
    let serialized_proof_payload = serde_json::json!({
        "receipts_root": receipts_root,
        "receipt_index": tx_index,
        "raw_receipts": all_block_receipts,
    });

    println!("🚀 Execution complete. Ready for zero-knowledge verification submission.");
    Ok(())
}